// Extract patient info and message from Twilio webhook
const twilioData = $input.first().json;

// Twilio webhook provides:
// - From: patient phone number
// - Body: SMS message text
// - To: refill line phone number

const patientPhone = twilioData.From || twilioData.from || '';
const messageText = twilioData.Body || twilioData.body || '';
const refillLineNumber = twilioData.To || twilioData.to || '';
const timestamp = new Date().toISOString();

// Clean phone number to E.164 format
let cleanPhone = patientPhone.trim();
if (!cleanPhone.startsWith('+')) {
  cleanPhone = '+1' + cleanPhone.replace(/\D/g, '');
}

// Clean message text
const cleanMessage = messageText.trim();

return {
  json: {
    patientPhone: cleanPhone,
    messageText: cleanMessage,
    refillLineNumber: refillLineNumber,
    requestTimestamp: timestamp,
    messageSid: twilioData.MessageSid || '',
    accountSid: twilioData.AccountSid || ''
  }
};

// Find patient by phone number
const patientPhone = $('Extract SMS Data').first().json.patientPhone;
const allPatients = $input.all();

let matchedPatient = null;

for (const item of allPatients) {
  const patient = item.json;
  const sheetPhone = patient.Phone || patient.phone || '';

  // Clean sheet phone for comparison
  let cleanSheetPhone = sheetPhone.trim();
  if (!cleanSheetPhone.startsWith('+')) {
    cleanSheetPhone = '+1' + cleanSheetPhone.replace(/\D/g, '');
  }

  if (cleanSheetPhone === patientPhone) {
    matchedPatient = patient;
    break;
  }
}

if (!matchedPatient) {
  // Patient not found
  return {
    json: {
      patientFound: false,
      patientPhone: patientPhone,
      error: 'Patient not found in database'
    }
  };
}

// Patient found - extract key data
return {
  json: {
    patientFound: true,
    patientId: matchedPatient.Patient_ID || '',
    patientName: matchedPatient.Patient_Name || matchedPatient.name || '',
    patientPhone: patientPhone,
    dateOfBirth: matchedPatient.Date_of_Birth || matchedPatient.dob || '',
    primaryDoctor: matchedPatient.Primary_Doctor || matchedPatient.doctor || 'Dr. Smith',
    lastVisitDate: matchedPatient.Last_Visit_Date || '',
    allergies: matchedPatient.Allergies || '',
    currentMedications: matchedPatient.Current_Medications || ''
  }
};

// Filter medications for this patient and build med list
const patientId = $('Find Patient Match').first().json.patientId;
const patientName = $('Find Patient Match').first().json.patientName;
const allMeds = $input.all();

const patientMeds = [];

for (const item of allMeds) {
  const med = item.json;

  // Match by Patient_ID or Patient_Name
  const medPatientId = med.Patient_ID || '';
  const medPatientName = med.Patient_Name || '';

  if (medPatientId === patientId || medPatientName === patientName) {
    patientMeds.push({
      medicationName: med.Medication_Name || '',
      dosage: med.Dosage || '',
      frequency: med.Frequency || '',
      prescribingDoctor: med.Prescribing_Doctor || '',
      lastFilled: med.Last_Filled_Date || '',
      refillsRemaining: med.Refills_Remaining || 0,
      controlledSubstance: med.Controlled_Substance === 'Yes' || med.Controlled_Substance === true,
      active: med.Status === 'Active' || med.active === true
    });
  }
}

if (patientMeds.length === 0) {
  return {
    json: {
      hasMedications: false,
      medicationCount: 0,
      medications: [],
      error: 'No active medications found for patient'
    }
  };
}

return {
  json: {
    hasMedications: true,
    medicationCount: patientMeds.length,
    medications: patientMeds
  }
};

// Use Claude AI to match patient's request text to their medication list
// This handles fuzzy matching like "blood pressure medicine" → "Lisinopril"

const messageText = $('Extract SMS Data').first().json.messageText;
const medications = $input.first().json.medications;
const patientName = $('Find Patient Match').first().json.patientName;

if (!medications || medications.length === 0) {
  return {
    json: {
      matched: false,
      error: 'No medications available to match'
    }
  };
}

// Build medication list for AI prompt
const medList = medications.map((med, idx) => 
  `${idx + 1}. ${med.medicationName} ${med.dosage} - ${med.frequency}`
).join('\n');

// Prepare for Claude AI node
return {
  json: {
    patientName: patientName,
    requestText: messageText,
    medicationList: medList,
    medications: medications,
    // This will be sent to Claude AI in next node
    promptForAI: `Patient ${patientName} sent this refill request: "${messageText}"

Their current medications are:
${medList}

Which medication is the patient requesting? If the request is ambiguous or doesn't match any medication, indicate that.

Respond in JSON format:
{
  "matchedMedication": "exact medication name from list or null",
  "confidence": 0.0-1.0,
  "reasoning": "brief explanation"
}`
  }
};
